<span class="line">        std<span class="token double-colon punctuation">::</span>unordered_map<span class="token operator">&lt;</span>std<span class="token double-colon punctuation">::</span>string<span class="token punctuation">,</span> size_t<span class="token operator">&gt;</span> byType<span class="token punctuation">;</span></span>
